SELECT p.id AS position_id, w.id AS wallet_position_id, w.symbol, w.quantity, w.average_entry_price_usdt, w.total_cost_usdt, w.stop_loss_usdt, w.take_profit_usdt, w.highest_price_usdt, w.profit_lock_active, w.profit_lock_state, w.profit_lock_price_usdt, w.profit_lock_progress_percent, w.profit_lock_activated_at, w.entry_stage, w.allocated_position_percent, w.entry_quality_score, w.near_tp_state, w.near_tp_best_price, w.near_tp_harvest_used, w.near_tp_harvested_quantity, w.status, w.opened_at, w.updated_at FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id AND w.symbol = p.symbol WHERE p.id IN (182,172,162,158,143,137) LIMIT 12